import portraitsJson from './portraits.json';
import creditsJson from './credits.json';
import coversJson from './covers.json';
import type { WorkView } from '../kunst/works';

// Well-known people of each country's history for the tiles: portraits.json (hand-written) +
// credits.json (generated by scripts/fetch-bilder.mjs geschichte). covers.json: country code → key.
interface Portrait { wiki: string; title: string; artist: string; year: string; file?: string }
interface Credit { file: string; author: string; licence: string; licenceUrl?: string; page: string }

const PORTRAITS = portraitsJson as Record<string, Portrait>;
const CREDITS = creditsJson as Record<string, Credit>;
export const COUNTRY_COVERS = coversJson as Record<string, string>;

export const hasGeschichtePortrait = (key: string) => key in PORTRAITS && key in CREDITS;
export const geschichteKeys = () => Object.keys(PORTRAITS);

export function geschichteView(key: string): WorkView | null {
  const p = PORTRAITS[key];
  const c = CREDITS[key];
  if (!p || !c) return null;
  const author = c.author === 'unbekannt' ? '' : `${c.author}, `;
  return {
    key,
    src: `/geschichte/${key}.jpg`,
    title: p.title,
    artist: p.artist,
    year: p.year,
    credit: c.licence.toLowerCase().startsWith('public domain') ? 'Gemeinfrei · Wikimedia Commons' : `Bild: ${author}${c.licence} · Wikimedia Commons`,
    page: c.page,
  };
}
